fn reload_activity_table(&mut self) -> Result<()> {
        *self.activity_view = self.conn.get_activity_view_with_str(
            self.activity_months.get_selected_value(),
            self.activity_years.get_selected_value(),
        )?;

        let old_table_position = self.activity_table.state;

        *self.activity_table = TableData::new(self.activity_view.get_activity_table());
        self.activity_table.state = old_table_position;

        Ok(())
    }

fn reload_add_tx_balance_data(&mut self) -> Result<()> {
        let is_editing_tx = self.add_tx_data.editing_tx;

        let mut current_table_index = if is_editing_tx {
            self.home_table.state.selected()
        } else {
            None
        };

        if self.add_tx_data.from_search {
            current_table_index = None;
        }

        *self.add_tx_balance = self.add_tx_data.generate_balance_section(
            self.home_txs,
            current_table_index,
            self.conn,
        )?;

        Ok(())
    }

fn reload_chart_data(&mut self) -> Result<()> {
        let fetch_nature = match self.chart_modes.index {
            0 => FetchNature::Monthly,
            1 => FetchNature::Yearly,
            2 => FetchNature::All,
            _ => panic!("Invalid chart mode"),
        };

        *self.chart_view = self.conn.get_chart_view_with_str(
            self.chart_months.get_selected_value(),
            self.chart_years.get_selected_value(),
            fetch_nature,
        )?;

        *self.chart_tx_methods = IndexedData::new_tx_methods_cumulative(self.conn);
        *self.chart_activated_methods = self
            .conn
            .get_tx_methods_cumulative()
            .into_iter()
            .map(|s| (s, true))
            .collect();

        Ok(())
    }

fn reload_home_table(&mut self, clear_lerp: bool) -> Result<()> {
        *self.home_txs = self.conn.fetch_txs_with_str(
            self.home_months.get_selected_value(),
            self.home_years.get_selected_value(),
            FetchNature::Monthly,
        )?;

        *self.home_table = TableData::new(self.home_txs.tx_array());

        if clear_lerp {
            self.lerp_state.clear_lerp(HOME_TABLE_ID);
        }

        Ok(())
    }

fn reload_recurring_table(&mut self) -> Result<()> {
        *self.recurring_txs = self.conn.get_recurring_txs()?;

        let old_table_position = self.recurring_table.state;

        let items = self
            .recurring_txs
            .iter()
            .map(FullRecurringTx::to_array)
            .collect();
        *self.recurring_table = TableData::new(items);
        self.recurring_table.state = old_table_position;

        Ok(())
    }

fn reload_summary(&mut self) -> Result<()> {
        let fetch_nature = match self.summary_modes.index {
            0 => FetchNature::Monthly,
            1 => FetchNature::Yearly,
            2 => FetchNature::All,
            _ => panic!("Invalid summary mode"),
        };

        let summary_view = self.conn.get_summary_with_str(
            self.summary_months.get_selected_value(),
            self.summary_years.get_selected_value(),
            fetch_nature,
        )?;

        *self.summary_sort = SortingType::Tags;

        let (previous_month, previous_year) = self.get_summary_previous_value();

        if let Some(month) = previous_month
            && let Some(year) = previous_year
        {
            let last_summary_view = self
                .conn
                .get_summary_with_str(&month, &year, fetch_nature)?;

            let last_full_summary = last_summary_view.generate_summary(None, self.conn);

            let mut summary_tags_table =
                summary_view.tags_array(Some(&last_summary_view), self.conn);

            summary_tags_table = sort_table_data(summary_tags_table, self.summary_sort);

            *self.summary_table = TableData::new(summary_tags_table);

            *self.full_summary = summary_view.generate_summary(Some(&last_full_summary), self.conn);

            *self.summary_view = summary_view;
        } else {
            let mut summary_tags_table = summary_view.tags_array(None, self.conn);
            summary_tags_table = sort_table_data(summary_tags_table, self.summary_sort);

            *self.summary_table = TableData::new(summary_tags_table);

            *self.full_summary = summary_view.generate_summary(None, self.conn);

            *self.summary_view = summary_view;
        }

        Ok(())
    }

fn reset_search_data(&mut self) {
        *self.search_table = TableData::new(Vec::new());
        *self.search_txs = SearchView::new_empty();
