pub fn home_ui(
    f: &mut Frame,
    months: &IndexedData,
    years: &IndexedData,
    home_table: &mut TableData,
    current_tab: &HomeTab,
    lerp_state: &mut LerpState,
    view_group: &mut TxViewGroup,
    theme: &Theme,
    conn: &mut DbConn,
) {
    let all_methods: Vec<String> = conn
        .get_tx_methods_sorted()
        .iter()
        .map(|m| m.name.clone())
        .collect();

    let mut width_data = Vec::new();
    let total_columns = all_methods.len() + 2;
    let width_percent = (100 / total_columns) as u16;

    for _ in 0..total_columns {
        width_data.push(Constraint::Percentage(width_percent));
    }

    let size = f.area();


    let selected_style_income = Style::default()
        .fg(theme.positive())
        .add_modifier(Modifier::REVERSED);
    let selected_style_expense = Style::default()
        .fg(theme.negative())
        .add_modifier(Modifier::REVERSED);

    let tx_count = home_table.items.len();
    let lerp_id = "home_tx_count";
    let lerp_tx_count = lerp_state.lerp(lerp_id, tx_count as f64, None) as i64;

    let lerp_tx_row = lerp_state.lerp(HOME_TABLE_ID, tx_count as f64, Some(0.50)) as i64;

    let table_name = format!("Transactions: {lerp_tx_count}");


    let header_cells = ["Date", "Details", "TX Method", "Amount", "Type", "Tags"]
        .iter()
        .map(|h| Cell::from(*h).style(Style::default().fg(theme.background())));

    let header = Row::new(header_cells)
        .style(Style::default().bg(theme.header()))
        .height(1)
        .bottom_margin(0);


    let rows = home_table
        .items
        .iter()
        .take(lerp_tx_row as usize)
        .enumerate()
        .map(|(row_index, item)| {
            let cells = item.iter().enumerate().map(|(index, c)| {
                let Ok(parsed_num) = c.parse::<f64>() else {
                    return Cell::from(c.separate_with_commas());
                };

                let lerp_id = format!("home_table:{index}:{row_index}");
                let new_c = lerp_state.lerp(&lerp_id, parsed_num, None);

                Cell::from(format!("{new_c:.2}").separate_with_commas())
            });
            Row::new(cells)
                .height(1)
                .bottom_margin(0)
                .style(Style::default().bg(theme.background()).fg(theme.text()))
        });





    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(2)
        .constraints([
            Constraint::Length(9),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(0),
        ])
        .split(size);

    f.render_widget(main_block(theme), size);

    let mut month_tab = create_tab(months, "Months", theme);

    let mut year_tab = create_tab(years, "Years", theme);





    let mut table_area = Table::new(
        rows,
        [
            Constraint::Percentage(13),
            Constraint::Percentage(35),
            Constraint::Percentage(13),
            Constraint::Percentage(13),
            Constraint::Percentage(8),
            Constraint::Percentage(18),
        ],
    )
    .header(header)
    .block(styled_block(&table_name, theme));

    let balance_array = view_group
        .balance_array(home_table.state.selected(), conn)
        .unwrap();

    let bal_data = balance_array.into_iter().map(|item| {
        let height = 1_u16;

        let row_type = HomeRow::get_row(&item);

        let mut index = 0;

        let cells = item.iter().map(|c| {
            let c = if row_type != HomeRow::TopRow
                && ![
                    "Balance",
                    "Changes",
                    "Income",
                    "Expense",
                    "Daily Income",
                    "Daily Expense",
                ]
                .contains(&c.as_str())
            {

                let symbol = if c.contains('↑') || c.contains('↓') {
                    c.chars().next()
                } else {
                    None
                };

                index += 1;


                let actual_data: f64 = if row_type != HomeRow::Changes {
                    c.parse().unwrap()
                } else if let Some(sym) = symbol {
                    let without_symbol = c.replace(sym, "");
                    without_symbol.parse().unwrap()
                } else {
                    c.parse().unwrap()
                };

                let lerp_id = format!("{row_type}:{index}");
                let to_show = lerp_state.lerp(&lerp_id, actual_data, None);



                if let Some(sym) = symbol {
                    format!("{sym}{to_show:.2}",).separate_with_commas()
                } else {
                    format!("{to_show:.2}").separate_with_commas()
                }
            } else {
                c.separate_with_commas()
            };

            if c.contains('↑') {
                Cell::from(c).style(Style::default().fg(theme.positive()))
            } else if c.contains('↓') {
                Cell::from(c).style(Style::default().fg(theme.negative()))
            } else if all_methods.contains(&c) || BALANCE_BOLD.contains(&c.as_str()) {
                Cell::from(c).style(Style::default().add_modifier(Modifier::BOLD))
            } else {
                Cell::from(c)
            }
        });
        Row::new(cells)
            .height(height)
            .bottom_margin(0)
            .style(Style::default().fg(theme.text()))
    });



    let balance_area = Table::new(bal_data, width_data.clone())
        .block(styled_block("Balance", theme))
        .style(Style::default().fg(theme.border()));

    match current_tab {


        HomeTab::Months => month_tab = month_tab.highlight_style(tab_highlight_style(theme)),
        HomeTab::Years => year_tab = year_tab.highlight_style(tab_highlight_style(theme)),

        HomeTab::Table => {
            if let Some(a) = home_table.state.selected() {
                table_area = table_area.highlight_symbol(">> ");

                let income_strings = ["Income", "Borrow", "Lend Repay"];
                let expense_strings = ["Expense", "Lend", "Borrow Repay"];

                let target_string = &home_table.items[a][4].as_str();

                if expense_strings.contains(target_string) {
                    table_area = table_area.row_highlight_style(selected_style_expense);
                } else if income_strings.contains(target_string) {
                    table_area = table_area.row_highlight_style(selected_style_income);
                } else if home_table.items[a][4] == "Transfer" {
                    let add_modifier = theme.add_reverse_modifier();

                    let mut style = Style::default();

                    if add_modifier {
                        style = style.fg(theme.selected()).add_modifier(Modifier::REVERSED);
                    } else {
                        style = style.bg(theme.selected());
                    }

                    table_area = table_area.row_highlight_style(style);
                }
            }
        }
    }


    if let Some(index) = home_table.state.selected()
        && index > 10
    {
        *home_table.state.offset_mut() = index - 10;
    }



    f.render_widget(balance_area, chunks[0]);
    f.render_widget(month_tab, chunks[2]);
    f.render_widget(year_tab, chunks[1]);


    f.render_stateful_widget(table_area, chunks[3], &mut home_table.state);
}

