pub fn summary_ui(
    f: &mut Frame,
    months: &IndexedData,
    years: &IndexedData,
    mode_selection: &IndexedData,
    table_data: &mut TableData,
    current_page: &SummaryTab,
    summary_hidden_mode: bool,
    summary_sort: &SortingType,
    lerp_state: &mut LerpState,
    full_summary: &FullSummary,
    theme: &Theme,
    conn: &mut DbConn,
) {
    let size = f.area();

    let tags_count = table_data.items.len();
    let lerp_id = "summary_tags_count";
    let lerp_tags_count = lerp_state.lerp(lerp_id, tags_count as f64, None) as i64;

    let lerp_row = lerp_state.lerp(SUMMARY_TABLE_ID, tags_count as f64, Some(0.50)) as usize;

    let tag_header = if let SortingType::Tags = summary_sort {
        "Tags ↑"
    } else {
        "Tags"
    };

    let total_income_header = if let SortingType::Income = summary_sort {
        "Total Income ↑"
    } else {
        "Total Income"
    };

    let total_expense_header = if let SortingType::Expense = summary_sort {
        "Total Expense ↑"
    } else {
        "Total Expense"
    };

    let mut tag_table_headers = vec![
        tag_header,
        total_income_header,
        total_expense_header,
        "Income %",
        "Expense %",
    ];

    let mut lend_borrow_headers = vec!["Borrow", "Lend"];

    if mode_selection.index == 0 {
        tag_table_headers.push("MoM Income %");
        tag_table_headers.push("MoM Expense %");

        lend_borrow_headers.push("MoM Borrow %");
        lend_borrow_headers.push("MoM Lend %");
    } else if mode_selection.index == 1 {
        tag_table_headers.push("YoY Income %");
        tag_table_headers.push("YoY Expense %");

        lend_borrow_headers.push("YoY Borrow %");
        lend_borrow_headers.push("YoY Lend %");
    }

    tag_table_headers.push("Borrow");
    tag_table_headers.push("Lend");

    let mut method_headers = vec!["Method", "Total Income", "Total Expense"];

    if mode_selection.index != 0 {
        method_headers.push("Average Income");
        method_headers.push("Average Expense");
    }

    method_headers.push("Income %");
    method_headers.push("Expense %");

    if mode_selection.index == 0 {
        method_headers.push("MoM Income %");
        method_headers.push("MoM Expense %");
    } else if mode_selection.index == 1 {
        method_headers.push("YoY Income %");
        method_headers.push("YoY Expense %");
    }

    let method_header_cells = method_headers
        .iter()
        .map(|h| Cell::from(*h).style(Style::default().fg(theme.background())));

    let tag_table_header_cells = tag_table_headers
        .into_iter()
        .map(|h| Cell::from(h).style(Style::default().fg(theme.background())));

    let lend_borrow_header_cells = lend_borrow_headers
        .into_iter()
        .map(|h| Cell::from(h).style(Style::default().fg(theme.background())));

    let tag_table_header = Row::new(tag_table_header_cells)
        .style(Style::default().bg(theme.header()))
        .height(1)
        .bottom_margin(0);

    let method_header = Row::new(method_header_cells)
        .style(Style::default().bg(theme.header()))
        .height(1)
        .bottom_margin(0);

    let lend_borrow_header = Row::new(lend_borrow_header_cells)
        .style(Style::default().bg(theme.header()))
        .height(1)
        .bottom_margin(0);

    let method_len = conn.get_tx_methods().len() as u16;

    let mut main_layout = Layout::default().direction(Direction::Vertical).margin(2);
    let mut summary_layout = Layout::default().direction(Direction::Horizontal);

    if summary_hidden_mode {
        main_layout = main_layout.constraints([
            Constraint::Length(method_len + 2),
            Constraint::Length(3),
            Constraint::Length(4),
            Constraint::Length(4),
            Constraint::Min(0),
        ]);
        summary_layout =
            summary_layout.constraints([Constraint::Percentage(50), Constraint::Percentage(50)]);
    } else {
        match mode_selection.index {
            0 => {
                main_layout = main_layout.constraints([
                    Constraint::Length(3),
                    Constraint::Length(3),
                    Constraint::Length(3),
                    Constraint::Length(method_len + 2),
                    Constraint::Length(3),
                    Constraint::Length(4),
                    Constraint::Length(4),
                    Constraint::Min(0),
                ]);
                summary_layout = summary_layout
                    .constraints([Constraint::Percentage(50), Constraint::Percentage(50)]);
            }
            1 => {
                main_layout = main_layout.constraints([
                    Constraint::Length(3),
                    Constraint::Length(3),
                    Constraint::Length(method_len + 2),
                    Constraint::Length(3),
                    Constraint::Length(4),
                    Constraint::Length(4),
                    Constraint::Min(0),
                ]);
                summary_layout = summary_layout
                    .constraints([Constraint::Percentage(50), Constraint::Percentage(50)]);
            }
            2 => {
                main_layout = main_layout.constraints([
                    Constraint::Length(3),
                    Constraint::Length(method_len + 2),
                    Constraint::Length(3),
                    Constraint::Length(4),
                    Constraint::Length(4),
                    Constraint::Min(0),
                ]);
                summary_layout = summary_layout
                    .constraints([Constraint::Percentage(50), Constraint::Percentage(50)]);
            }
            _ => {}
        }
    }

    let chunks = main_layout.split(size);



    let summary_chunk = if summary_hidden_mode {
        summary_layout.split(chunks[3])
    } else {
        summary_layout.split(chunks[6 - mode_selection.index])
    };

    f.render_widget(main_block(theme), size);

    let mut month_tab = create_tab(months, "Months", theme);

    let mut year_tab = create_tab(years, "Years", theme);

    let mut mode_selection_tab = create_tab(mode_selection, "Modes", theme);


    let rows = table_data
        .items
        .iter()
        .take(lerp_row)
        .enumerate()
        .map(|(row_index, item)| {
            let cells = item.iter().enumerate().map(|(index, c)| {
                if index == 0 {
                    return Cell::from(c.clone());
                }

                let lerp_id = format!("summary_table_main:{index}:{row_index}");

                let Ok(parsed_num) = c.parse::<f64>() else {
                    if c == "∞" {
                        let new_c = lerp_state.lerp(&lerp_id, 0.0, None);
                        return Cell::from(format!("{new_c:.2}").separate_with_commas());
                    }

                    let symbol = if c.contains('↑') || c.contains('↓') {
                        c.chars().next()
                    } else {
                        None
                    };

                    if let Some(sym) = symbol {
                        let c = c.replace(sym, "");
                        if let Ok(parsed_num) = c.parse::<f64>() {
                            let new_c = lerp_state.lerp(&lerp_id, parsed_num, None);

                            return Cell::from(format!("{sym}{new_c:.2}").separate_with_commas());
                        }
                    }
