            match first_letter.to_ascii_lowercase() {
                'd' => return RecurrenceFrequency::Daily,
                'w' => return RecurrenceFrequency::Weekly,
                'm' => return RecurrenceFrequency::Monthly,
                'y' => return RecurrenceFrequency::Yearly,
